    case 'num': return n.v
    case 'bool': return n.v
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a) : err('#REF!')
    }
    case 'un': {
      const x = num(evaluate(n.x))
      if (isErr(x)) return x
      return n.op === '-' ? -x : x
    }
    case 'bin': {
      const l = evaluate(n.l), r = evaluate(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (isErr(l)) return l
        if (isErr(r)) return r
        const c = compare(l, r)
        switch (n.op) {
          case '=': return c === 0
          case '<>': return c !== 0
          case '<': return c < 0
          case '<=': return c <= 0
          case '>': return c > 0
          default: return c >= 0
        }
      }
      const x = num(l)
      if (isErr(x)) return x
      const y = num(r)
      if (isErr(y)) return y
      switch (n.op) {
        case '+': return finite(x + y)
        case '-': return finite(x - y)
        case '*': return finite(x * y)
        case '/': return y === 0 ? err('#DIV/0!') : finite(x / y)
        default: return finite(Math.pow(x, y))
      }
    }
    case 'call': return callFn(n)
  }
}

function callFn(n) {
  const { name, args } = n
  const ag = args.length
  switch (name) {
    case 'ABS': {
      if (ag !== 1) return err('#ERR!')
      const v = num(scalar(argValues(args[0])))
      return isErr(v) ? v : Math.abs(v)
    }
    case 'IF': {
      if (ag !== 3) return err('#ERR!')
      const c = scalar(argValues(args[0]))
      if (isErr(c)) return c
      if (typeof c === 'string') return err('#VALUE!')
      const t = typeof c === 'boolean' ? c : c !== 0
      return scalar(argValues(args[t ? 1 : 2]))
    }
    case 'SUM': case 'MIN': case 'MAX': case 'COUNT': case 'AVG': {
      if (ag < 1) return err('#ERR!')
      const vals = []
      for (const a of args) vals.push(...argValues(a))
      for (const v of vals) if (isErr(v)) return v
      if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
      const nums = []
      for (const v of vals) {
        const x = num(v)
        if (isErr(x)) return x
        nums.push(x)
      }
      if (name === 'SUM') return finite(nums.reduce((a, b) => a + b, 0))
      if (name === 'MIN') return Math.min(...nums)
      if (name === 'MAX') return Math.max(...nums)
      return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
    default: return err('#NAME?')
  }
}

// ---------- output
const sorted = [...cells.values()].sort((a, b) => key(a.addr) - key(b.addr))
const out = []
for (const cell of sorted) {
  const name = nameOf(cell.addr)
  if (mode === 'values') {
    const v = cellValue(cell.addr)
    let s
    if (isErr(v)) s = v.e
    else if (typeof v === 'boolean') s = v ? 'TRUE' : 'FALSE'
    else if (typeof v === 'number') s = String(Number(v.toPrecision(10)))
    else s = v
    out.push(`${name}=${s}`)
  } else {
    const ast = getAst(cell)
    let line = `${name}:`
    if (ast) {
      const set = new Map()
      collect(ast, set)
      for (const a of [...set.values()].sort((x, y) => key(x) - key(y))) line += ` ${nameOf(a)}`
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
